module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
)(
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    // Dual-port RAM
    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) dual_port_ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );

    // Write pointer logic
    reg [ADDR_WIDTH:0] waddr_bin;
    wire [ADDR_WIDTH:0] wptr;
    wire [ADDR_WIDTH:0] wptr_buff;
    wire [ADDR_WIDTH:0] wptr_syn;

    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            waddr_bin <= 0;
        end else if (winc & ~wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end

    assign waddr = waddr_bin[ADDR_WIDTH-1:0];
    assign wptr = {~waddr_bin[ADDR_WIDTH], waddr_bin[ADDR_WIDTH-1:0]};

    always @(posedge rclk or negedge wrstn) begin
        if (~wrstn) begin
            wptr_buff <= 0;
        end else begin
            wptr_buff <= wptr;
        end
    end

    always @(posedge rclk or negedge wrstn) begin
        if (~wrstn) begin
            wptr_syn <= 0;
        end else begin
            wptr_syn <= wptr_buff;
        end
    end

    assign wfull = (wptr == ~rptr_syn);

    // Read pointer logic
    reg [ADDR_WIDTH:0] raddr_bin;
    wire [ADDR_WIDTH:0] rptr;
    wire [ADDR_WIDTH:0] rptr_buff;
    wire [ADDR_WIDTH:0] rptr_syn;

    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            raddr_bin <= 0;
        end else if (rinc & ~rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end

    assign raddr = raddr_bin[ADDR_WIDTH-1:0];
    assign rptr = {~raddr_bin[ADDR_WIDTH], raddr_bin[ADDR_WIDTH-1:0]};

    always @(posedge wclk or negedge rrstn) begin
        if (~rrstn) begin
            rptr_buff <= 0;
        end else begin
            rptr_buff <= rptr;
        end
    end

    always @(posedge wclk or negedge rrstn) begin
        if (~rrstn) begin
            rptr_syn <= 0;
        end else begin
            rptr_syn <= rptr_buff;
        end
    end

    assign rempty = (rptr == rptr_syn);

    // Read and write enable logic
    assign wen = winc & ~wfull;
    assign ren = rinc & ~rempty;

endmodule
